/** One month of a register: confirmed (frozen) or not yet (the live count). */
export interface MonthlyReturnOut {
  /** Which register's return */
  kind: "SentinelEvents" | "Complaints";
  /** The first day of the month */
  month: string;
  confirmed: boolean;
  /** Entries of the month; 0 on a confirmed return is the documented nil return */
  entries: number;
  /** The entries counted (incident or complaint numbers) */
  numbers: string[];
  /** Entries of a confirmed month reported after it was confirmed */
  late_entries: string[];
  note: string | null;
  confirmed_at: string | null;
  confirmed_by_name: string | null;
  confirm_stamp: AuthorStampOut | null;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface MonthlyReturnIn {
  /** Which register's return */
  kind: "SentinelEvents" | "Complaints";
  /** Any day of the month that ended; the return covers the whole month */
  month: string;
  /** E.g. how the Quality Officer made sure nothing went unreported */
  note?: string | null;
}

