/** Incident statistics — GET /api/v1/incidents/statistics (who may call: holders of incident.view). */
export function incidentStatistics(query?: { date_from?: string | null; date_to?: string | null }): Promise<IncidentStatisticsOut> {
  return api<IncidentStatisticsOut>("GET", withQuery(`/incidents/statistics`, query), undefined);
}

/** The incident register for a period (PDF) — GET /api/v1/incidents/register/pdf (who may call: holders of incident.view). */
export function registerPdfIncidents(query: { date_from: string; date_to: string }): Promise<unknown> {
  return api<unknown>("GET", withQuery(`/incidents/register/pdf`, query), undefined);
}

/** The monthly returns of a register, nil returns included — GET /api/v1/quality/monthly-returns (who may call: holders of incident.view or complaint.view). */
export function listReturnsQualityMonthly(query: { kind: "SentinelEvents" | "Complaints"; months?: number }): Promise<MonthlyReturnOut[]> {
  return api<MonthlyReturnOut[]>("GET", withQuery(`/quality/monthly-returns`, query), undefined);
}

/** Confirm a month's return (none is an answer too) — POST /api/v1/quality/monthly-returns (who may call: holders of incident.manage or complaint.manage). */
export function confirmReturn(body: MonthlyReturnIn): Promise<MonthlyReturnOut> {
  return api<MonthlyReturnOut>("POST", `/quality/monthly-returns`, body, { idempotent: true });
}

/** The incident register — GET /api/v1/incidents (who may call: holders of incident.view or incident.report or ot.clinical_statistics.view). */
export function listIncidents(query?: { status?: "Reported" | "UnderReview" | "Analysed" | "Closed" | "Withdrawn" | null; type_code?: string | null; area?: "Clinical" | "Medication" | "Anaesthesia" | "Surgery" | "Diagnostics" | "Transfusion" | "Infection" | "MotherAndBaby" | "Behaviour" | "Facility" | "Occupational" | null; sentinel_only?: boolean; harm?: "NoHarm" | "Mild" | "Moderate" | "Severe" | "Death" | null; department_id?: number | null; booking_id?: number | null; patient_id?: number | null; date_from?: string | null; date_to?: string | null; mine?: boolean; open_only?: boolean; limit?: number }): Promise<IncidentOut[]> {
  return api<IncidentOut[]>("GET", withQuery(`/incidents`, query), undefined);
}
